wait.definition:
var promise = new Promise(function(resolve, reject) {
  setTimeout(function() {
    resolve({
      seconds_waited: new Numbas.jme.types.TNum(time)
    })
  }, time*50);
});
return new Numbas.jme.types.TPromise(promise);

parts.customMarkingAlgorithm:
pre_submit: 
  [ wait(studentNumber + a) ]

mark:
  feedback("a is {a}");
  feedback("studentnumber is {studentnumber}");
  feedback("waited {pre_submit['seconds_waited']}");
  apply(base_mark)

q:
  apply_marking_script("numberentry",studentAnswer,settings+["minvalue":4,"maxvalue":5],1)

r:
  apply_marking_script("numberentry",studentAnswer,settings+["minvalue":3,"maxvalue":4],1)

mark:
  feedback("number between 4 and 5");
  concat_feedback(q["mark"]["feedback"],marks/2);
  feedback("number between 3 and 4");
  concat_feedback(r["mark"]["feedback"],marks/2)

